// Pick the touch copy and mint an opt-out token.
// One node instead of a Switch plus three near-identical email nodes.
const cfg = $vars ?? {};
const j = $input.first().json;
const nth = Number(j.touch_number ?? 0);          // 0-based: 0 = first touch
const brand = cfg.brand ?? 'we';
const booking = cfg.booking_url ?? '';

const TOUCHES = [
  { subject: `Following up on your ${brand} enquiry`,
    body: `<p>Hi ${j.name},</p><p>Just checking you got our reply. If it is easier to talk it through, grab a slot here:</p><p><a href="${booking}">Book a consultation</a></p>` },
  { subject: `Still happy to help — ${brand}`,
    body: `<p>Hi ${j.name},</p><p>No rush at all. When you are ready, the calendar is open:</p><p><a href="${booking}">Book a consultation</a></p>` },
  { subject: `Closing the loop`,
    body: `<p>Hi ${j.name},</p><p>I will stop following up here so I am not cluttering your inbox. If the timing changes, the door is open.</p><p><a href="${booking}">Book a consultation</a></p>` },
];
const t = TOUCHES[Math.min(nth, TOUCHES.length - 1)];

// Opaque, unguessable, and stored server-side -- an HMAC in a URL is replayable
// forever and leaks through browser history and edge logs.
const token = [...crypto.getRandomValues(new Uint8Array(24))]
  .map(b => b.toString(16).padStart(2, '0')).join('');

return [{ json: {
  lead_id: j.lead_id, name: j.name, email_norm: j.email_norm,
  touch_number: nth, subject: t.subject, body: t.body, token,
  unsubscribe_url: `${cfg.webhook_base}/webhook/lead-stage?t=${token}`,
  followup_days: JSON.parse(cfg.followup_days ?? '[3,7,14]'),
} }];
